<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require_permission('view_reports');
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$params=[$from,$to];$scopeSql='';$scopeParams=[];
if(!is_super_admin()){$ids=assigned_location_ids();if(!$ids){$scopeSql=' AND 1=0';}else{$ph=implode(',',array_fill(0,count($ids),'?'));$scopeSql=" AND EXISTS (SELECT 1 FROM sale_items sx WHERE sx.sale_id=s.id) AND NOT EXISTS (SELECT 1 FROM sale_items sy WHERE sy.sale_id=s.id AND sy.location_id NOT IN ($ph))";$scopeParams=$ids;}}
$locFilter=(int)($_GET['location_id']??0);if($locFilter>0&&can_access_location($locFilter)){$scopeSql.=' AND EXISTS (SELECT 1 FROM sale_items slf WHERE slf.sale_id=s.id AND slf.location_id=?)';$scopeParams[]=$locFilter;}else{$locFilter=0;}
$base=" FROM sales s JOIN users u ON u.id=s.cashier_id WHERE DATE(s.created_at) BETWEEN ? AND ?".$scopeSql;$allParams=array_merge($params,$scopeParams);
$st=db()->prepare('SELECT COALESCE(SUM(CASE WHEN s.status=\'CANCELLED\' THEN 0 ELSE GREATEST(s.grand_total-s.refund_total,0) END),0) net_sales,COUNT(*) bills'.$base);$st->execute($allParams);$tot=$st->fetch();$sales=(float)$tot['net_sales'];$billCount=(int)$tot['bills'];
$limit=isset($_GET['export'])?5000:1000;$st=db()->prepare('SELECT s.*,u.name cashier'.$base.' ORDER BY s.id DESC LIMIT '.$limit);$st->execute($allParams);$rows=$st->fetchAll();
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="pratyangi_sales_'.$from.'_to_'.$to.'.csv"');$o=fopen('php://output','w');fputcsv($o,['Invoice','Date','Customer','Cashier','Payment','Status','Gross','Refund','Net']);foreach($rows as $r){$refund=(float)$r['refund_total'];$net=$r['status']==='CANCELLED'?0:max(0,(float)$r['grand_total']-$refund);fputcsv($o,[$r['invoice_no'],$r['created_at'],$r['customer_name'],$r['cashier'],$r['payment_mode'],$r['status'],$r['grand_total'],$refund,$net]);}fclose($o);exit;}
if(($_GET['export']??'')==='xlsx'){require __DIR__.'/../app/xlsx.php';$out=[['Invoice','Date','Customer','Cashier','Payment','Status','Gross','Refund','Net']];foreach($rows as $r){$refund=(float)$r['refund_total'];$net=$r['status']==='CANCELLED'?0:max(0,(float)$r['grand_total']-$refund);$out[]=[$r['invoice_no'],$r['created_at'],$r['customer_name']?:'Walk-in',$r['cashier'],$r['payment_mode'],$r['status'],(float)$r['grand_total'],$refund,$net];}xlsx_download('pratyangi_sales_'.$from.'_to_'.$to.'.xlsx',$out,'Sales');}
$locList=[];if(is_super_admin()){$locList=db()->query('SELECT id,code,name FROM locations WHERE active=1 ORDER BY code')->fetchAll();}else{$ids=assigned_location_ids();if($ids){$ph=implode(',',array_fill(0,count($ids),'?'));$lst=db()->prepare("SELECT id,code,name FROM locations WHERE active=1 AND id IN ($ph) ORDER BY code");$lst->execute($ids);$locList=$lst->fetchAll();}}
$exportQs='from='.urlencode($from).'&to='.urlencode($to).($locFilter?'&location_id='.$locFilter:'');
$margin=null;if(is_super_admin()){$st=db()->prepare("SELECT si.quantity,si.taxable_value,si.cost_snapshot,COALESCE((SELECT SUM(sri.quantity) FROM sale_return_items sri WHERE sri.sale_item_id=si.id),0) returned FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE s.status<>'CANCELLED' AND DATE(s.created_at) BETWEEN ? AND ?");$st->execute([$from,$to]);$margin=0.0;foreach($st->fetchAll() as $i){$remaining=max(0,(float)$i['quantity']-(float)$i['returned']);if($remaining<=0)continue;$ratio=$remaining/max(0.000001,(float)$i['quantity']);$netExTax=(float)$i['taxable_value']*$ratio;$margin+=$netExTax-$remaining*(float)$i['cost_snapshot'];}}
page_header('Sales Reports');?>
<form method="get" class="actions no-print"><input type="date" name="from" value="<?=e($from)?>"><input type="date" name="to" value="<?=e($to)?>"><select name="location_id"><option value="">All locations</option><?php foreach($locList as $lo):?><option value="<?=(int)$lo['id']?>"<?=$locFilter===(int)$lo['id']?' selected':''?>><?=e($lo['code'].' · '.$lo['name'])?></option><?php endforeach;?></select><button class="btn">Apply</button><a class="btn secondary" href="?<?=e($exportQs)?>&export=csv">Export CSV</a><a class="btn secondary" href="?<?=e($exportQs)?>&export=xlsx">Export Excel</a><button type="button" class="btn secondary" onclick="window.print()">Print / Save PDF</button></form><br><div class="grid"><div class="card"><div class="muted">Net Sales</div><div class="metric">₹<?=e(number_format($sales,2))?></div></div><div class="card"><div class="muted">Bills</div><div class="metric"><?=e($billCount)?></div></div><?php if($margin!==null):?><div class="card"><div class="muted">Gross Margin After Returns/Discount · Admin Only</div><div class="metric">₹<?=e(number_format($margin,2))?></div></div><?php endif;?></div><br>
<table><tr><th>Invoice</th><th>Date</th><th>Customer</th><th>Cashier</th><th>Payment</th><th>Status</th><th>Gross</th><th>Refund</th><th>Net</th></tr><?php foreach($rows as $r):$refund=(float)($r['refund_total']??0);$net=$r['status']==='CANCELLED'?0:max(0,(float)$r['grand_total']-$refund);?><tr><td><a href="invoice.php?id=<?=$r['id']?>"><?=e($r['invoice_no'])?></a></td><td><?=e($r['created_at'])?></td><td><?=e($r['customer_name']?:'Walk-in')?></td><td><?=e($r['cashier'])?></td><td><?=e($r['payment_mode'])?></td><td><?=e($r['status'])?></td><td>₹<?=e(number_format($r['grand_total'],2))?></td><td>₹<?=e(number_format($refund,2))?></td><td>₹<?=e(number_format($net,2))?></td></tr><?php endforeach;?></table><?php page_footer();
